"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[919],{80919:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-hollow-cross.png\\"\\n          title=\\"공허한 십자가\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"자음과모음\\"\\n          publishedDate=\\"2014-09-15\\"\\n          isbn=\\"9788957078150\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n시간을 넘나드는 세 개의 살인 사건을 통해 하나의 거대한 비극을 완성한다.  \\n각 사건은 독립적으로 보이지만, 과거의 원죄가 현재의 비극을 낳는 필연적인 인과관계로 묶여 있다.  \\n소설의 다층적 서사 구조를 시간순으로 재구성하고, 이들이 어떻게 하나의 진실로 수렴되는지 분석한다.  \\n<br>\\n<mark>사람을 죽인 자는 어떻게 속죄해야 하는가?</mark>\\n이는 단순히 범죄자를 법의 심판대에 세우는 차원을 넘어, 인간의 양심, 구원, 그리고 형벌의 진정한 의미에 대한 깊은 철학적 탐구를 요구한다.  \\n<br>\\n<mark>공허한 십자가</mark>는 누가 짊어지는가?  \\n가해자, 유족, 그리고 사법 제도 모두의 공허한 십자가를 암시한다.  \\n<br>\\n이 작품은 <mark>십자가의 전이</mark>라는 역설적인 현실을 고발한다.  "}')}}]);